macro_rules! deps {
    () => {
        TraitsWithDefaultImpl!();
        CrossCrateTraitsDefined!();
        CrossCrateTraits!();
    };
}

macro_rules! orphan_check_impl {
    () => {
        deps!();
        # [instrument (level = "debug" , skip (tcx))] pub (crate) fn orphan_check_impl (tcx : TyCtxt < '_ > , impl_def_id : LocalDefId ,) -> Result < () , ErrorGuaranteed > { let trait_ref = tcx . impl_trait_ref (impl_def_id) . unwrap () . instantiate_identity () ; trait_ref . error_reported () ? ; match orphan_check (tcx , impl_def_id , OrphanCheckMode :: Proper) { Ok (()) => { } Err (err) => match orphan_check (tcx , impl_def_id , OrphanCheckMode :: Compat) { Ok (()) => match err { OrphanCheckErr :: UncoveredTyParams (uncovered_ty_params) => { lint_uncovered_ty_params (tcx , uncovered_ty_params , impl_def_id) } OrphanCheckErr :: NonLocalInputType (_) => { bug ! ("orphanck: shouldn't've gotten non-local input tys in compat mode") } } , Err (err) => return Err (emit_orphan_check_error (tcx , trait_ref , impl_def_id , err)) , } , } let trait_def_id = trait_ref . def_id ; debug ! ("trait_ref={:?} trait_def_id={:?} trait_is_auto={}" , trait_ref , trait_def_id , tcx . trait_is_auto (trait_def_id)) ; if tcx . trait_is_auto (trait_def_id) { let self_ty = trait_ref . self_ty () ; enum LocalImpl { Allow , Disallow { problematic_kind : & 'static str } , } enum NonlocalImpl { Allow , DisallowBecauseNonlocal , DisallowOther , } let (local_impl , nonlocal_impl) = match self_ty . kind () { ty :: Adt (self_def , _) => (LocalImpl :: Allow , if self_def . did () . is_local () { NonlocalImpl :: Allow } else { NonlocalImpl :: DisallowBecauseNonlocal } ,) , ty :: Foreign (did) => (LocalImpl :: Allow , if did . is_local () { NonlocalImpl :: Allow } else { NonlocalImpl :: DisallowBecauseNonlocal } ,) , ty :: Dynamic (..) => (LocalImpl :: Disallow { problematic_kind : "trait object" } , NonlocalImpl :: DisallowOther ,) , ty :: Param (..) => (if self_ty . is_sized (tcx , ty :: TypingEnv :: non_body_analysis (tcx , impl_def_id)) { LocalImpl :: Allow } else { LocalImpl :: Disallow { problematic_kind : "generic type" } } , NonlocalImpl :: DisallowOther ,) , ty :: Alias (kind , _) => { let problematic_kind = match kind { ty :: Projection => "associated type" , ty :: Free => "type alias" , ty :: Opaque => "opaque type" , ty :: Inherent => "associated type" , } ; (LocalImpl :: Disallow { problematic_kind } , NonlocalImpl :: DisallowOther) } ty :: Pat (..) => (LocalImpl :: Disallow { problematic_kind : "pattern type" } , NonlocalImpl :: DisallowOther ,) , ty :: Bool | ty :: Char | ty :: Int (..) | ty :: Uint (..) | ty :: Float (..) | ty :: Str | ty :: Array (..) | ty :: Slice (..) | ty :: RawPtr (..) | ty :: Ref (..) | ty :: FnDef (..) | ty :: FnPtr (..) | ty :: Never | ty :: Tuple (..) | ty :: UnsafeBinder (_) => (LocalImpl :: Allow , NonlocalImpl :: DisallowOther) , ty :: Closure (..) | ty :: CoroutineClosure (..) | ty :: Coroutine (..) | ty :: CoroutineWitness (..) | ty :: Bound (..) | ty :: Placeholder (..) | ty :: Infer (..) => { let sp = tcx . def_span (impl_def_id) ; span_bug ! (sp , "weird self type for autotrait impl") } ty :: Error (..) => (LocalImpl :: Allow , NonlocalImpl :: Allow) , } ; if trait_def_id . is_local () { match local_impl { LocalImpl :: Allow => { } LocalImpl :: Disallow { problematic_kind } => { return Err (tcx . dcx () . emit_err (errors :: TraitsWithDefaultImpl { span : tcx . def_span (impl_def_id) , traits : tcx . def_path_str (trait_def_id) , problematic_kind , self_ty , })) ; } } } else { match nonlocal_impl { NonlocalImpl :: Allow => { } NonlocalImpl :: DisallowBecauseNonlocal => { return Err (tcx . dcx () . emit_err (errors :: CrossCrateTraitsDefined { span : tcx . def_span (impl_def_id) , traits : tcx . def_path_str (trait_def_id) , })) ; } NonlocalImpl :: DisallowOther => { return Err (tcx . dcx () . emit_err (errors :: CrossCrateTraits { span : tcx . def_span (impl_def_id) , traits : tcx . def_path_str (trait_def_id) , self_ty , })) ; } } } } Ok (()) }
    };
}

orphan_check_impl!();